<?php require_once __DIR__.'/alumno_common.php'; $stmt=$pdo->prepare("SELECT m.nombre AS materia,m.clave,i.estatus,c.parcial1,c.parcial2,c.parcial3,c.calificacion_final FROM inscripciones i JOIN materia_profesor mp ON mp.id=i.asignacion JOIN materias m ON m.id=mp.materia LEFT JOIN calificaciones c ON c.inscripcion=i.id WHERE i.alumno=? ORDER BY m.nombre");$stmt->execute([$alumnoActual['id']]);$calificaciones=$stmt->fetchAll(); $conNotas=array_filter($calificaciones,fn($r)=>$r['calificacion_final']!==null); $promedioCapturado=count($conNotas)?array_sum(array_map(fn($r)=>(float)$r['calificacion_final'],$conNotas))/count($conNotas):null; alumno_layout('Calificaciones','Consulta tus evaluaciones parciales y finales','calificacionesAlumno.html',compact('calificaciones','promedioCapturado'));
